from collections import deque

class Solution:
    def magicalString(self, n: int) -> int:
        if n <= 3:
            return int(n > 0)
        pending = deque([2])
        produced, ones, digit = 3, 1, 1
        while produced < n:
            count = pending.popleft()
            for _ in range(count):
                pending.append(digit)
                produced += 1
                if produced <= n and digit == 1:
                    ones += 1
            digit = 3 - digit
        return ones
